/* Standalone syntax/type check of the exact statements added by the port.
 * The min() macro and _STK_LIM value are copied verbatim from the target tree
 * (include/linux/kernel.h:713-717, include/uapi/linux/resource.h:65).
 * rlimit() is declared to return unsigned long to mirror the target's
 * static inline unsigned long rlimit(unsigned int) in include/linux/sched.h.
 * This is NOT a kernel build; it only proves the added expressions type-check.
 */
#define _STK_LIM (8*1024*1024)
#define RLIMIT_STACK 3

#define min(x, y) ({				\
	typeof(x) _min1 = (x);			\
	typeof(y) _min2 = (y);			\
	(void) (&_min1 == &_min2);		\
	_min1 < _min2 ? _min1 : _min2; })

unsigned long rlimit(unsigned int limit);
extern unsigned long argv_storage_size;

int check_bound(void)
{
	unsigned long limit;

	/* exact ported statements */
	limit = _STK_LIM / 4 * 3;
	limit = min(limit, rlimit(RLIMIT_STACK) / 4);
	if (argv_storage_size > limit)
		return -1;	/* mirrors goto fail */
	return 0;
}

